create table if not exists observations(id uuid primary key default uuid_generate_v4(),indicator_id uuid not null references indicators(id) on delete restrict,period_id uuid not null references periods(id) on delete restrict,breakdown jsonb not null default '{}'::jsonb,breakdown_key text not null default '',value numeric not null,unit text not null,scale text not null default 'units',is_provisional boolean not null default false,document_id uuid references documents(id) on delete restrict,page_number integer,table_ref text,status text not null default 'staged',extraction_method text not null default 'manual',verified_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(status in ('staged','verified','published','rejected','superseded')));
create table if not exists extraction_runs(id uuid primary key default uuid_generate_v4(),document_id uuid not null references documents(id) on delete cascade,method text not null,started_at timestamptz not null default now(),finished_at timestamptz,rows_found integer not null default 0,notes text,created_at timestamptz not null default now());
create table if not exists query_log(id uuid primary key default uuid_generate_v4(),question text not null,query_plan jsonb,matched boolean not null default false,created_at timestamptz not null default now());
